    throw new TypeError('records must be an array');
  }

  const grouped = {};
  for (const record of records) {
    const bucketKey = String(record?.[key]);
    if (!grouped[bucketKey]) {
      grouped[bucketKey] = [];
    }
    grouped[bucketKey].push(record);
  }
  return grouped;
}

